    "zh-CN": "示例脚本描述"
  },
  "i18nName": {
    "en-US": "Example Script",
    "zh-CN": "示例脚本"
  },
  "i18nIntroduction": {
    "en-US": "This is an example script",
    "zh-CN": "这是一个示例脚本"
  },
  "i18nVideo": {
    "en-US": "",
    "zh-CN": ""
  },
